-- Editorial first release: no scholar/clinical approval implied.
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('diabetes-and-prophetic-medicine','diabetes-and-prophetic-medicine','Diabetes and Prophetic Medicine','السكري والطب النبوي','Authentic healing sources and the clinical limits of traditional remedies','prophetic_medicine','concept','Diabetes is a modern diagnosis, not an illness named in an authenticated Prophetic-era treatment protocol. This entry distinguishes Quranic healing references and traditional food practices from evidence-based diabetes management.','Introductory source-led reference','diabetes, diabetic, blood sugar, type 1 diabetes, type 2 diabetes, sugar disease, diabetes treatment, prophetic medicine diabetes, insulin, glucose','Qualified scholarly/clinical expert review pending','editorial_draft','published','50');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('diabetes-and-prophetic-medicine-s1','diabetes-and-prophetic-medicine','Identifying the condition','overview','Diabetes describes several medical conditions in which the body cannot regulate blood glucose normally. Type 1 and type 2 diabetes have different mechanisms, and treatment depends on the actual diagnosis and individual assessment. A named Prophetic medicine should not be inferred for a modern condition simply because both involve health or healing.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('diabetes-and-prophetic-medicine-s2','diabetes-and-prophetic-medicine','What Islamic primary texts provide','scripture','Quran 26:80 attributes healing to Allah in the speech of Ibrahim. Quran 16:69 discusses healing in relation to what emerges from bees. Hadith reports also describe black seed and foods. These sources matter for Islamic understanding and history, but none of those passages specifically establishes a clinical diabetes treatment or substitutes for a diagnosis.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('diabetes-and-prophetic-medicine-s3','diabetes-and-prophetic-medicine','Modern research and the evidence boundary','science','The NIH National Center for Complementary and Integrative Health reviews research on dietary supplements for diabetes. Evidence varies by preparation and study quality, and supplements may interact with treatment. Lab studies or small clinical trials do not show that a retail black-seed oil or honey product can replace insulin or other prescribed diabetes medication.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('diabetes-and-prophetic-medicine-s4','diabetes-and-prophetic-medicine','Protecting health and faith','safety','Do not stop insulin or other prescribed treatment because of a traditional medicine claim. Symptoms of severe low or high glucose, dehydration or serious illness require prompt medical attention. Spiritual practice and professional treatment can coexist; ongoing diabetes or complications do not indicate defective faith. This article provides no individualized doses, treatment algorithm or medical diagnosis.','4');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('diabetes-and-prophetic-medicine-s5','diabetes-and-prophetic-medicine','Ramadan and food traditions','practice','A person considering Ramadan fasting with diabetes should seek an individual assessment from their diabetes-care team and qualified religious counsel. Diabetes UK explains that illness may create fasting exemptions and that fasting can have significant risks depending on medication and glucose control. Honey and dates have cultural and religious significance but still contribute carbohydrates to the diet.','5');
