INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,verification_status,sort_order) VALUES('diabetes-and-prophetic-medicine-r2','diabetes-and-prophetic-medicine','quran','The Quran — Surah Ash-Shuara','26:80','https://quran.com/26/80','pending','2');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,verification_status,sort_order) VALUES('diabetes-and-prophetic-medicine-r3','diabetes-and-prophetic-medicine','clinical','Diabetes UK — Diabetes and Ramadan','Risk and religious considerations','https://www.diabetes.org.uk/about-diabetes/looking-after-diabetes/ramadan','pending','3');
INSERT OR IGNORE INTO encyclopedia_articles(id,slug,title,arabic_title,subtitle,domain,entry_type,abstract,identity_text,alternate_names,editorial_note,review_status,status,sort_order) VALUES('mens-clothing-prophetic-era','mens-clothing-prophetic-era','Men''s Clothing in the Prophetic Era','لباس الرجال في السيرة','The qamis, turban, cloak and clothing ethics in transmitted reports','seerah','historical','Authentic narrations and collections describe the qamis, turbans, trousers, cloaks and white garments. These references offer insight into clothing in the Prophet''s time without proving that one modern national outfit is compulsory.','Introductory source-led reference','clothing for men, mens clothing, men''s clothing, mens dress, male clothes, clothing men, male garment, qamis, turban, cloak, thobe, prophet clothing, seerah dress','Qualified scholarly/clinical expert review pending','editorial_draft','published','51');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('mens-clothing-prophetic-era-s1','mens-clothing-prophetic-era','History rather than a costume catalogue','historical','Clothing in the Prophet''s Arabian setting reflected climate, trade, work and cultural practice. A specific term in a Hadith does not supply a complete illustrated tailoring pattern. Names such as qamis, izar, turban and cloak are best examined through their reported usage, context and later linguistic scholarship.','1');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('mens-clothing-prophetic-era-s2','mens-clothing-prophetic-era','A report concerning the qamis','transmission','Jami at-Tirmidhi 1762 reports from Umm Salamah that the qamis was a favored garment of the Prophet. Its source also discusses the transmission and includes a hasan gharib characterization. A report of preference should not be converted into a claim that all Muslim men must wear the same modern garment or buy a religiously certified product.','2');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('mens-clothing-prophetic-era-s3','mens-clothing-prophetic-era','White clothing in the narration','transmission','Sunan Abi Dawud 4061 records encouragement regarding white garments. The page also provides an authenticity grading and full narration context. Readers should distinguish the original words from simplified fashion claims, and consider whether a specific teaching indicates commendation, custom or a legal obligation through accountable scholarship.','3');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('mens-clothing-prophetic-era-s4','mens-clothing-prophetic-era','Turbans, shirts and pilgrimage','historical','Sahih al-Bukhari 5803 mentions shirts, turbans, trousers and cloaks in response to a question about dress for someone in ihram. The list documents garment vocabulary, but the stated prohibition applies to the pilgrimage situation in the narration. It would be misleading to apply that restricted context to ordinary daily clothing for all men.','4');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('mens-clothing-prophetic-era-s5','mens-clothing-prophetic-era','Theological and ethical framework','interpretation','Quran 7:26 discusses clothing, covering and adornment while placing moral emphasis on righteousness. Modesty, cleanliness, social custom and specific legal rules should be studied as distinct questions. This encyclopedia indexes historical and narrated references; qualified scholars should be consulted for personal rulings, disputed dress practices and interpretations.','5');
INSERT OR IGNORE INTO encyclopedia_sections(id,article_id,heading,section_type,body,sort_order) VALUES('mens-clothing-prophetic-era-s6','mens-clothing-prophetic-era','Source and reconstruction caution','methodology','The Arabic wording, transmission strength and historical interpretation need separate checking. Illustrations of historical garments should be labeled reconstruction, not photography. Fashion retail listings must not borrow the authority of an authentic narration to claim that a brand is uniquely Sunnah-compliant.','6');
